DROP TABLE IF EXISTS `adecuacionmovimientos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `adecuacionmovimientos` (
  `Id` int NOT NULL AUTO_INCREMENT,
  `AdecuacionId` int NOT NULL,
  `TipoOperacion` varchar(20) NOT NULL,
  `ClavePresupuestal` varchar(100) NOT NULL,
  `PresupuestoCalendarizadoId` int DEFAULT NULL,
  `Enero` decimal(18,2) DEFAULT '0.00',
  `Febrero` decimal(18,2) DEFAULT '0.00',
  `Marzo` decimal(18,2) DEFAULT '0.00',
  `Abril` decimal(18,2) DEFAULT '0.00',
  `Mayo` decimal(18,2) DEFAULT '0.00',
  `Junio` decimal(18,2) DEFAULT '0.00',
  `Julio` decimal(18,2) DEFAULT '0.00',
  `Agosto` decimal(18,2) DEFAULT '0.00',
  `Septiembre` decimal(18,2) DEFAULT '0.00',
  `Octubre` decimal(18,2) DEFAULT '0.00',
  `Noviembre` decimal(18,2) DEFAULT '0.00',
  `Diciembre` decimal(18,2) DEFAULT '0.00',
  `MontoTotal` decimal(18,2) DEFAULT '0.00',
  PRIMARY KEY (`Id`),
  KEY `AdecuacionId` (`AdecuacionId`),
  KEY `fk_adecmov_presup` (`PresupuestoCalendarizadoId`),
  KEY `idx_adecmov_clave` (`ClavePresupuestal`),
  CONSTRAINT `adecuacionmovimientos_ibfk_1` FOREIGN KEY (`AdecuacionId`) REFERENCES `adecuaciones` (`Id`) ON DELETE CASCADE,
  CONSTRAINT `fk_adecmov_presup` FOREIGN KEY (`PresupuestoCalendarizadoId`) REFERENCES `presupuestocalendarizado` (`Id`)
) ENGINE=InnoDB AUTO_INCREMENT=6680 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
