--
-- Table structure for table `gastos`
--

DROP TABLE IF EXISTS `gastos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `gastos` (
  `Id` int NOT NULL AUTO_INCREMENT,
  `PresupuestoCalendarizadoId` int NOT NULL,
  `Folio` varchar(50) DEFAULT NULL,
  `UnificaContrato` varchar(100) DEFAULT NULL,
  `Beneficiario` varchar(255) DEFAULT NULL,
  `Factura` varchar(100) DEFAULT NULL,
  `ConceptoGasto` text,
  `Ministracion` varchar(50) DEFAULT NULL,
  `Importe` decimal(18,2) NOT NULL,
  `Estatus` varchar(50) DEFAULT 'Pendiente',
  `FechaRegistro` datetime DEFAULT CURRENT_TIMESTAMP,
  `TipoMinistracionId` int DEFAULT NULL,
  PRIMARY KEY (`Id`),
  KEY `PresupuestoCalendarizadoId` (`PresupuestoCalendarizadoId`),
  KEY `fk_gas_tm` (`TipoMinistracionId`),
  CONSTRAINT `fk_gas_tm` FOREIGN KEY (`TipoMinistracionId`) REFERENCES `cat_tipoministracion` (`Id`),
  CONSTRAINT `gastos_ibfk_1` FOREIGN KEY (`PresupuestoCalendarizadoId`) REFERENCES `presupuestocalendarizado` (`Id`)
) ENGINE=InnoDB AUTO_INCREMENT=308 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

