CREATE TABLE `ingresos_presupuesto` (
  `Id` int NOT NULL AUTO_INCREMENT,
  `RubroIngresoId` int DEFAULT NULL,
  `Monto` decimal(18,2) DEFAULT '0.00',
  `FechaRegistro` datetime DEFAULT NULL,
  `AnioGastoId` int DEFAULT NULL,
  `OrgPubId` int DEFAULT NULL,
  PRIMARY KEY (`Id`),
  KEY `fk_ing_ri` (`RubroIngresoId`),
  KEY `fk_ingreso_anio` (`AnioGastoId`),
  KEY `fk_ingreso_orgpub` (`OrgPubId`),
  CONSTRAINT `fk_ing_ri` FOREIGN KEY (`RubroIngresoId`) REFERENCES `cat_rubroingresos` (`Id`),
  CONSTRAINT `fk_ingreso_anio` FOREIGN KEY (`AnioGastoId`) REFERENCES `cat_aniogasto` (`Id`),
  CONSTRAINT `fk_ingreso_orgpub` FOREIGN KEY (`OrgPubId`) REFERENCES `cat_orgpub` (`Id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
