--
-- Table structure for table `ministraciones`
--

DROP TABLE IF EXISTS `ministraciones`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ministraciones` (
  `Id` int NOT NULL AUTO_INCREMENT,
  `id_tipoministracion_folio` int DEFAULT NULL,
  `Folio` varchar(50) NOT NULL COMMENT 'Folio unico de la ministracion',
  `PresupuestoCalendarizadoId` int DEFAULT NULL,
  `id_tipo_recurso` int DEFAULT NULL,
  `id_programa_fondo` int DEFAULT NULL,
  `Id_sub_fuente_financiamiento` int DEFAULT NULL,
  `Id_proyecto_estrategico` int DEFAULT NULL,
  `id_digito_ministracion` int DEFAULT NULL,
  `id_fuente_financiamiento` int DEFAULT NULL,
  `Id_ramo` int DEFAULT NULL,
  `id_tipo_ministracion` int DEFAULT NULL,
  `ClavePresupuestal` longtext NOT NULL,
  `Mes` int NOT NULL COMMENT '1=Enero, 2=Febrero, etc.',
  `Anio` int NOT NULL DEFAULT '2026' COMMENT 'Ano de la ministracion',
  `Importe_total` decimal(18,2) NOT NULL DEFAULT '0.00' COMMENT 'Monto autorizado/ministerado',
  `Concepto` varchar(500) DEFAULT NULL,
  `Estatus` varchar(20) NOT NULL DEFAULT 'REGISTRADA' COMMENT 'REGISTRADA, AUTORIZADA, PAGADA, CANCELADA',
  `FechaCreacion` datetime DEFAULT CURRENT_TIMESTAMP,
  `UsuarioCreacion` varchar(50) DEFAULT NULL,
  `FechaModificacion` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`Id`),
  UNIQUE KEY `Folio_UNIQUE` (`Folio`),
  KEY `fk_min_presupuesto` (`PresupuestoCalendarizadoId`),
  KEY `fk_min_programa` (`id_programa_fondo`),
  KEY `fk_min_digito` (`id_digito_ministracion`),
  KEY `fk_min_tipo` (`id_tipo_ministracion`),
  KEY `fk_min_fuente_cat` (`id_fuente_financiamiento`),
  KEY `fk__idx` (`id_tipoministracion_folio`),
  KEY `fk_min_tipo_recurso_cat_idx` (`id_tipo_recurso`),
  KEY `fk_sub_financiamiento_cat_idx` (`Id_sub_fuente_financiamiento`),
  KEY `fk_proy_estrategico_cat_idx` (`Id_proyecto_estrategico`),
  KEY `fk_ramo_cat_idx` (`Id_ramo`),
  CONSTRAINT `fk_min_digito_min_cat` FOREIGN KEY (`id_digito_ministracion`) REFERENCES `cat_digitosministracion` (`Id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_min_fuente_cat` FOREIGN KEY (`id_fuente_financiamiento`) REFERENCES `cat_fuentefinanciamiento` (`Id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_min_presupuesto` FOREIGN KEY (`PresupuestoCalendarizadoId`) REFERENCES `presupuestocalendarizado` (`Id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_min_programa_fondo_cat` FOREIGN KEY (`id_programa_fondo`) REFERENCES `cat_programafondo` (`Id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_min_tipo_min_cat` FOREIGN KEY (`id_tipo_ministracion`) REFERENCES `cat_tipoministracion` (`Id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_min_tipo_min_folio_cat` FOREIGN KEY (`id_tipoministracion_folio`) REFERENCES `cat_tipoministracionfolio` (`Id`),
  CONSTRAINT `fk_min_tipo_recurso_cat` FOREIGN KEY (`id_tipo_recurso`) REFERENCES `cat_tiporecurso` (`Id`),
  CONSTRAINT `fk_proy_estrategico_cat` FOREIGN KEY (`Id_proyecto_estrategico`) REFERENCES `cat_proyectoestrategico` (`Id`),
  CONSTRAINT `fk_sub_financiamiento_cat` FOREIGN KEY (`Id_sub_fuente_financiamiento`) REFERENCES `cat_subfuentefinanciamiento` (`Id`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
