DROP TABLE IF EXISTS `presupuestocalendarizado`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `presupuestocalendarizado` (
  `Id` int NOT NULL AUTO_INCREMENT,
  `Secuencia` varchar(50) DEFAULT NULL,
  `Marca` varchar(50) DEFAULT NULL,
  `ClavePresupuestal` varchar(150) NOT NULL,
  `UrId` int DEFAULT NULL,
  `UroId` int DEFAULT NULL,
  `FinalidadId` int DEFAULT NULL,
  `FuncionId` int DEFAULT NULL,
  `SubfuncionId` int DEFAULT NULL,
  `SubsubfuncionId` int DEFAULT NULL,
  `ProgramaSectorialId` int DEFAULT NULL,
  `ProgramaPresupuestarioId` int DEFAULT NULL,
  `OrigenAsignacionId` int DEFAULT NULL,
  `ActividadInstitucionalId` int DEFAULT NULL,
  `MunicipioId` int DEFAULT NULL,
  `ObjetoGastoId` int DEFAULT NULL,
  `TipoGastoId` int DEFAULT NULL,
  `TipoRecursoId` int DEFAULT NULL,
  `FuenteFinanciamientoId` int DEFAULT NULL,
  `SubfuenteFinanciamientoId` int DEFAULT NULL,
  `RamoId` int DEFAULT NULL,
  `ProgramaFondoId` int DEFAULT NULL,
  `DigitoMinistracionId` int DEFAULT NULL,
  `Aprobado` decimal(18,2) DEFAULT '0.00',
  `PorLiberar` decimal(18,2) DEFAULT '0.00',
  `Liberado` decimal(18,2) DEFAULT '0.00',
  `Enero` decimal(18,2) DEFAULT '0.00',
  `Febrero` decimal(18,2) DEFAULT '0.00',
  `Marzo` decimal(18,2) DEFAULT '0.00',
  `Abril` decimal(18,2) DEFAULT '0.00',
  `Mayo` decimal(18,2) DEFAULT '0.00',
  `Junio` decimal(18,2) DEFAULT '0.00',
  `Julio` decimal(18,2) DEFAULT '0.00',
  `Agosto` decimal(18,2) DEFAULT '0.00',
  `Septiembre` decimal(18,2) DEFAULT '0.00',
  `Octubre` decimal(18,2) DEFAULT '0.00',
  `Noviembre` decimal(18,2) DEFAULT '0.00',
  `Diciembre` decimal(18,2) DEFAULT '0.00',
  `Aumentos` decimal(18,2) DEFAULT '0.00',
  `Disminuciones` decimal(18,2) DEFAULT '0.00',
  `Modificado` decimal(18,2) GENERATED ALWAYS AS (((`Aprobado` + `Aumentos`) - `Disminuciones`)) STORED,
  `Ministrado` decimal(18,2) DEFAULT '0.00',
  `Devengado` decimal(18,2) DEFAULT '0.00',
  `Pagado` decimal(18,2) DEFAULT '0.00',
  `Disponibilidad` decimal(18,2) GENERATED ALWAYS AS ((`Modificado` - `Devengado`)) STORED,
  `Economias` decimal(18,2) DEFAULT '0.00',
  `ProyectoEstrategicoId` int DEFAULT NULL,
  `OrientacionGastoId` int DEFAULT NULL,
  `AsignacionGastoId` int DEFAULT NULL,
  `AnioGastoId` int DEFAULT NULL,
  `ClasificacionAdministrativaId` int DEFAULT NULL,
  PRIMARY KEY (`Id`),
  KEY `UrId` (`UrId`),
  KEY `UroId` (`UroId`),
  KEY `FinalidadId` (`FinalidadId`),
  KEY `FuncionId` (`FuncionId`),
  KEY `SubfuncionId` (`SubfuncionId`),
  KEY `SubsubfuncionId` (`SubsubfuncionId`),
  KEY `ProgramaSectorialId` (`ProgramaSectorialId`),
  KEY `ProgramaPresupuestarioId` (`ProgramaPresupuestarioId`),
  KEY `OrigenAsignacionId` (`OrigenAsignacionId`),
  KEY `ActividadInstitucionalId` (`ActividadInstitucionalId`),
  KEY `MunicipioId` (`MunicipioId`),
  KEY `ObjetoGastoId` (`ObjetoGastoId`),
  KEY `TipoGastoId` (`TipoGastoId`),
  KEY `TipoRecursoId` (`TipoRecursoId`),
  KEY `FuenteFinanciamientoId` (`FuenteFinanciamientoId`),
  KEY `SubfuenteFinanciamientoId` (`SubfuenteFinanciamientoId`),
  KEY `RamoId` (`RamoId`),
  KEY `ProgramaFondoId` (`ProgramaFondoId`),
  KEY `DigitoMinistracionId` (`DigitoMinistracionId`),
  KEY `fk_pc_pe` (`ProyectoEstrategicoId`),
  KEY `fk_pc_og` (`OrientacionGastoId`),
  KEY `fk_pc_ag` (`AsignacionGastoId`),
  KEY `fk_pc_anio` (`AnioGastoId`),
  KEY `fk_pc_ca` (`ClasificacionAdministrativaId`),
  CONSTRAINT `fk_pc_ag` FOREIGN KEY (`AsignacionGastoId`) REFERENCES `cat_asignaciongasto` (`Id`),
  CONSTRAINT `fk_pc_anio` FOREIGN KEY (`AnioGastoId`) REFERENCES `cat_aniogasto` (`Id`),
